export function getControl(id        )                      {
  return CONTROLS.find((c) => c.id === id);
}

export function controlsByCategory()                         {
  const map = new Map                   ();
  for (const control of CONTROLS) {
    const list = map.get(control.category) ?? [];
    list.push(control);
    map.set(control.category, list);
  }
  return map;
}
